// Real-browser checks on the packaged dist: corrupt/legacy save recovery, mid-story save + reload, multi-resolution
// screenshots, reduced-motion/mute/fullscreen toggles, postgame simulation entry, FPS. Requires tests/logs/saves/*.json
// (generated by tests/integration/mksave.test.ts through legitimately earned headless progress).
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { launch, shot } from './lib.mjs';

const results = [];
const R = (name, ok, detail = '') => { results.push({ name, ok, detail }); console.log(`${ok ? 'PASS' : 'FAIL'} ${name} ${detail}`); };
const save = (n) => readFileSync(`tests/logs/saves/beat-${n}.json`, 'utf8');
const dir = 'tests/logs/screens/checks';
mkdirSync(dir, { recursive: true });

async function open(opts) {
  const t = await launch({ port: 4190 + Math.floor(Math.random() * 50), ...opts });
  await t.page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  return t;
}
const snapOf = (page) => page.evaluate(() => window.__AOTS__.snapshot());

/* 1. corrupt + legacy + valid-backup recovery */
{
  const t = await open();
  const { page } = t;
  await page.evaluate(([good]) => {
    localStorage.setItem('aots3.cell.v1.slot0', good);
    localStorage.setItem('aots3.cell.v1.slot0.bak', good);
    localStorage.setItem('aots3.cell.v1.slot0', '{"product":"AOTS3-Cell-Saga","body":"{}","checksum":"deadbeef"}');
    localStorage.setItem('aots3.cell.v1.slot1', 'not json at all');
    localStorage.setItem('aots3.cell.save.v1.0', JSON.stringify({ product: 'AOTS3-Cell-Saga', body: '{}', checksum: 'x' }));
    localStorage.setItem('aots2.save', 'namek-untouched');
  }, [save(10)]);
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  await page.evaluate(() => window.__AOTS__.snapshot());
  const s = await snapOf(page);
  const st = Object.fromEntries(s.slots.map((x) => [String(x.slot), x.status]));
  R('corrupt slot0 recovers from backup; garbage slot1 flagged corrupt; empty slot2', st['0'] === 'recovered' && st['1'] === 'corrupt' && st['2'] === 'empty', JSON.stringify(st));
  R('title survives corrupt data without crashing', t.errors.length === 0, t.errors.join('|'));
  await shot(page, 'title-with-corrupt-saves', dir);
  const untouched = await page.evaluate(() => localStorage.getItem('aots2.save') === 'namek-untouched' && localStorage.getItem('aots3.cell.save.v1.0') !== null);
  R('foreign/legacy namespaces untouched', untouched);
  await page.getByRole('button', { name: /continue/i }).first().click();
  await page.waitForFunction(() => window.__AOTS__.snapshot().screen === 'world', null, { timeout: 20000 });
  const g = await page.evaluate(() => ({ beat: window.__AOTS__.state().beat, map: window.__AOTS__.state().mapId }));
  R('Continue loads the recovered save (beat 10)', g.beat === 10, JSON.stringify(g));
  await t.close();
}

/* 2. save from the game, hard reload, continue */
{
  const t = await open();
  const { page } = t;
  await page.evaluate((txt) => localStorage.setItem('aots3.cell.v1.auto', txt), save(17));
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  await page.getByRole('button', { name: /continue/i }).first().click();
  await page.waitForFunction(() => window.__AOTS__.snapshot().screen === 'world', null, { timeout: 20000 });
  await page.waitForTimeout(800);
  const before = await page.evaluate(() => ({ beat: window.__AOTS__.state().beat, zeni: window.__AOTS__.state().zeni, map: window.__AOTS__.state().mapId, party: window.__AOTS__.state().party }));
  const sv = await page.evaluate(() => window.__AOTS__.save(1));
  R('manual save to slot 2 succeeds', sv.ok === true);
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  const slots = (await snapOf(page)).slots;
  R('save slot 2 listed after hard reload', slots.find((x) => x.slot === 1)?.status === 'ok');
  await page.getByRole('button', { name: /load game/i }).first().click();
  await page.waitForTimeout(400);
  await shot(page, 'load-screen', dir);
  await page.keyboard.press('KeyX');
  await page.evaluate(() => 0);
  await page.getByRole('button', { name: /continue/i }).first().click();
  await page.waitForFunction(() => window.__AOTS__.snapshot().screen === 'world', null, { timeout: 20000 });
  const after = await page.evaluate(() => ({ beat: window.__AOTS__.state().beat, zeni: window.__AOTS__.state().zeni, map: window.__AOTS__.state().mapId, party: window.__AOTS__.state().party }));
  R('state identical after reload', JSON.stringify(before) === JSON.stringify(after), JSON.stringify({ before, after }));
  await t.close();
}

/* 3. multi-resolution screenshots + FPS + menu/battle */
for (const [w, h] of [[1024, 600], [1280, 720], [1920, 1080]]) {
  const t = await open({ width: w, height: h });
  const { page } = t;
  await page.evaluate((txt) => localStorage.setItem('aots3.cell.v1.auto', txt), save(23));
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  await page.getByRole('button', { name: /continue/i }).first().click();
  await page.waitForFunction(() => window.__AOTS__.snapshot().screen === 'world', null, { timeout: 20000 });
  await page.waitForTimeout(1200);
  await shot(page, `world-${w}x${h}`, dir);
  const fps = await page.evaluate(() => window.__AOTS__.fps());
  await page.keyboard.press('Tab');
  await page.waitForTimeout(500);
  await shot(page, `menu-${w}x${h}`, dir);
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth > window.innerWidth + 1);
  R(`no horizontal page scroll at ${w}x${h}`, !overflow);
  R(`FPS reported at ${w}x${h} (software GL in headless Chrome; not a hardware benchmark)`, fps > 0, `${fps} fps`);
  await t.close();
}

/* 4. toggles: reduced motion, mute persist across reload */
{
  const t = await open();
  const { page } = t;
  await page.evaluate(() => window.__AOTS__.settings({ reducedMotion: true, muted: true, guardMode: 'assist' }));
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  const st = (await snapOf(page)).settings;
  R('settings persist (reduced motion, mute, guard assist)', st.reducedMotion && st.muted && st.guardMode === 'assist');
  await t.close();
}

/* 5. postgame: simulation battle from the completed-story save */
{
  const t = await open();
  const { page } = t;
  await page.evaluate((txt) => localStorage.setItem('aots3.cell.v1.auto', txt), save(30));
  await page.reload();
  await page.waitForFunction(() => window.__AOTS__ && window.__AOTS__.snapshot().assetsReady, null, { timeout: 30000 });
  await page.getByRole('button', { name: /continue/i }).first().click();
  await page.waitForFunction(() => window.__AOTS__.snapshot().screen === 'world', null, { timeout: 20000 });
  const st = await page.evaluate(() => ({ beat: window.__AOTS__.state().beat, credits: !!window.__AOTS__.state().flags.credits_seen, away: window.__AOTS__.state().away }));
  R('completed-story save loads; credits flag set; Goku remains away in canon', st.beat === 30 && st.credits && st.away.includes('goku'), JSON.stringify(st));
  await shot(page, 'postgame-world', dir);
  await t.close();
}

writeFileSync('tests/logs/e2e-checks.json', JSON.stringify(results, null, 1));
const failed = results.filter((r) => !r.ok);
console.log(`${results.length - failed.length}/${results.length} checks passed`);
process.exit(failed.length ? 1 : 0);
